using System;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;
using Microsoft.Build.Framework;

var reader = new BinLogReader();
int errors = 0, warnings = 0, messages = 0;

reader.ErrorRaised += (sender, args) =>
{
    errors++;
    var e = (BuildErrorEventArgs)args;
    Console.WriteLine($"ERROR [{e.ProjectFile}] {e.File}({e.LineNumber},{e.ColumnNumber}): error {e.Code}: {e.Message}");
};

reader.WarningRaised += (sender, args) =>
{
    warnings++;
    var w = (BuildWarningEventArgs)args;
    Console.WriteLine($"WARNING [{w.ProjectFile}] {w.File}({w.LineNumber},{w.ColumnNumber}): warning {w.Code}: {w.Message}");
};

reader.MessageRaised += (sender, args) =>
{
    messages++;
};

reader.BuildFinished += (sender, args) =>
{
    var e = (BuildFinishedEventArgs)args;
    Console.WriteLine($"BUILD FINISHED: Succeeded={e.Succeeded}");
};

var events = reader.Replay(args[0]);
Console.WriteLine($"Total: {errors} errors, {warnings} warnings, {messages} messages");

// Try structured log approach
var build = BinaryLog.ReadBuild(args[0]);
Console.WriteLine($"\nBuild succeeded: {build.Succeeded}");
Console.WriteLine($"Build children count: {build.Children.Count}");

void PrintErrors(BaseNode node, int depth = 0)
{
    if (node is Error err)
    {
        Console.WriteLine($"  STRUCTURED ERROR: {err.Text}");
    }
    if (node is Warning warn)
    {
        Console.WriteLine($"  STRUCTURED WARNING: {warn.Text}");
    }
    if (node is TreeNode tn)
    {
        foreach (var child in tn.Children)
        {
            if (child is BaseNode bn) PrintErrors(bn, depth + 1);
        }
    }
}

PrintErrors(build);
EOF

